  end

  # "Removing a line from a non-draft sends no removal, and its entries stay reserved, including for invoices created
  # before the boundary". A seed only fills a missing row; it never overwrites one the invoice already has.
  it "removing a line from a sent invoice that already has a holding leaves the holding and the entry lock unchanged" do
    invoice = create(:invoice, company: existing_holding_company, client: existing_holding_client, status: :sent)
    kept_line = create(:invoice_line_item, invoice:, timesheet_entry: existing_holding_spec_entry, rate: 100, quantity: 60)
